#!/bin/sh
# Generated by scripts/localize.py.
cfm_message() {
    case "$1:$CFM_LANGUAGE" in
        installer.firstInstall:en) shift; printf '%s: first installation; file access will be requested during setup.\n' "$@" ;;
        installer.firstInstall:zh) shift; printf '%s：首次安装，将在设置加载项时请求文件访问。\n' "$@" ;;
        installer.accessFailed:en) shift; printf '%s: could not renew Office file access for %s: %s. Retry installation.\n' "$@" ;;
        installer.accessFailed:zh) shift; printf '%s：无法为%s重新请求Office文件访问。原因：%s。请重新安装。\n' "$@" ;;
    esac
}
